import json

populations = {
    "London": 9.1,
    "Paris": 2.06,
    "Berlin": 3.9
}

names = list(populations.keys())
diffs = {}

for i in range(len(names)):
    for j in range(i + 1, len(names)):
        city1, city2 = names[i], names[j]
        diff = abs(populations[city1] - populations[city2])
        diffs[(city1, city2)] = diff

closest_pair = min(diffs, key=diffs.get)

print(json.dumps({
    "populations": populations,
    "differences": {f"{k[0]}-{k[1]}": v for k, v in diffs.items()},
    "closest_pair": list(closest_pair),
    "min_difference": diffs[closest_pair],
    "verdict": "Berlin-London"
}))
